import {dayKey} from './store.js';
import {pillars,bosses} from './game-data.js';
import {goalStatuses,daysApart,readiness,equipmentAllows,currentLevel,evaluateLevel,trialMeets} from './training.js';
import {weeklyPersonalSummary,eventStart} from './schedule.js';
export function playerLevel(xp,configuration){const c=configuration||{levelBase:500,levelStep:100};let level=1,total=0,cost=c.levelBase;while(xp>=total+cost){total+=cost;level++;cost=c.levelBase+(level-1)*c.levelStep}return {level,xp,total,into:xp-total,next:cost,remaining:total+cost-xp,percent:(xp-total)/cost*100}}
export function balances(data){return data.rewardLedger.reduce((s,r)=>({xp:s.xp+r.amount,coins:s.coins+r.coins}),{xp:0,coins:0})}
export function nextCelebration(data,pref){if(data.sessions.some(s=>['active','paused'].includes(s.status)&&!s.supersededBy))return null;const intensity=pref.celebrationIntensity||(pref.celebrations===false?'Off':'Minimal');if(intensity==='Off')return null;return data.gameCelebrations.filter(c=>!c.seen).sort((a,b)=>({boss:0,level:1,badge:2}[a.type]-{boss:0,level:1,badge:2}[b.type]))[0]||null}
export const safeSession=s=>s.status==='completed'&&!s.supersededBy&&!(s.revision>0)&&s.logs.length>0&&!s.logs.some(l=>l.pain)&&s.logs.some(l=>l.reps>0||l.durationSeconds>0||l.distanceMeters>0);
export function programmedComplete(s){return safeSession(s)&&s.exercises.every((e,i)=>{const logs=s.logs.filter(l=>l.exercise===i&&(!e.exerciseId||l.exerciseId===e.exerciseId));return logs.length>=e.sets&&logs.slice(0,e.sets).every(l=>(e.durationSeconds>0?l.durationSeconds>=e.durationSeconds:e.distanceMeters>0?l.distanceMeters>=e.distanceMeters:l.reps>=e.reps)&&((e.resistanceKind==='assistance'||['assisted-dip','assisted-pullup'].includes(e.exerciseId))?(e.weight===0&&!s.proof||l.weight<=e.weight):l.weight>=e.weight))})}
export function sessionPillars(s,library){if(!programmedComplete(s))return [];if(s.pillarId)return [s.pillarId];const result=new Set();for(const e of s.exercises){const x=library.find(x=>x.id===e.exerciseId||x.name===e.name);if(!x)continue;if(['pull','push','grip'].includes(x.relatedDominancePath))result.add('body');if(x.category==='Mobility')result.add('mobility');if(x.resistance==='weighted'&&x.category!=='Mobility')result.add('strength');if(x.movementType==='locomotion')result.add('movement')}return [...result]}
export function pillarState(data,date){const plan=data.pillarPlans.find(p=>p.id===date);return pillars.map(p=>({...p,planned:plan?.items.find(i=>i.id===p.id)?.planned??true,mode:plan?.items.find(i=>i.id===p.id)?.mode||'Normal',completion:plan?.completed?.[p.id]||null}))}
export function dailyClear(data,date){const state=data.dailyStates.find(s=>s.id===date),plan=data.pillarPlans.find(p=>p.id===date);if(!plan)return false;const required=plan.items.filter(i=>i.planned);const routines=state?.routineTasks||[];return required.every(i=>plan.completed[i.id])&&routines.every((_,i)=>data.routineLogs.some(l=>l.date===date&&l.task===i&&l.done))&&(!plan.requireWater||data.water.filter(w=>w.date===date).reduce((n,w)=>n+w.amount,0)>=(plan.waterTarget||80))&&data.sessions.filter(s=>s.date===date&&['Main','Second'].includes(s.kind)&&!s.supersededBy).every(s=>s.status==='completed')}
export function activityDates(data,type='active'){const dates=new Set();for(const s of data.sessions.filter(s=>s.status==='completed'&&!s.supersededBy&&s.logs.some(l=>!l.pain&&(l.reps>0||l.durationSeconds>0||l.distanceMeters>0)))){const category=s.exercises.map(e=>data.exercises.find(x=>x.id===e.exerciseId||x.name===e.name)?.category);if(type==='active'||type==='training'||type==='mobility'&&(s.mode==='Recovery'||category.includes('Mobility'))||type==='walking'&&s.exercises.some(e=>e.exerciseId==='walk'))dates.add(s.date)}if(type==='routine'||type==='active')for(const d of data.dailyStates){const tasks=d.routineTasks||[];if(tasks.length&&tasks.every((_,i)=>data.routineLogs.some(l=>l.date===d.date&&l.task===i&&l.done)))dates.add(d.date)}if(type==='active')for(const c of data.checkins)dates.add(c.date);return [...dates].sort()}
export function streak(dates,today){const ordered=[...new Set(dates)].filter(d=>d<=today).sort();let best=0,run=0,last=null;for(const date of ordered){run=last&&daysApart(date,last)===1?run+1:1;best=Math.max(best,run);last=date}let current=0;if(last&&daysApart(today,last)<=1){let day=last;const set=new Set(ordered);while(set.has(day)){current++;const d=new Date(day+'T12:00:00');d.setDate(d.getDate()-1);day=dayKey(d)}}return {current,best,last}}
export function comeback(data,today){const dates=activityDates(data);const previous=dates.filter(d=>d<today).at(-1);return {returned:dates.includes(today)&&!!previous&&daysApart(today,previous)>1,gap:previous?daysApart(today,previous)-1:0,lastWorkout:data.sessions.filter(s=>s.status==='completed'&&s.date<today).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}}
export function weekStart(date){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d)}
export function trend(rows,key,date,c){const valid=rows.filter(r=>Number.isFinite(r[key])&&r.date<=date).sort((a,b)=>a.date.localeCompare(b.date));const unique=Object.values(Object.fromEntries(valid.map(r=>[r.date,r])));const end=unique.at(-1)?.date;const recent=unique.filter(r=>end&&daysApart(end,r.date)<c.trendDays);const baseline=unique.filter(r=>unique[0]&&daysApart(r.date,unique[0].date)<c.trendDays);const nonoverlap=baseline.length>=c.minimumSamples&&recent.length>=c.minimumSamples&&baseline.at(-1).date<recent[0].date;const mean=values=>values.length?values.reduce((sum,r)=>sum+r[key],0)/values.length:null;return {baseline:mean(baseline),recent:mean(recent),change:nonoverlap?mean(baseline)-mean(recent):null,baselineIds:baseline.map(r=>r.id),recentIds:recent.map(r=>r.id),enough:nonoverlap}}
export function transformationSummary(data,date){const config=data.configurations.find(c=>c.id==='transformation'),economy=data.gameConfigurations.find(c=>c.id==='economy'),start=data.preferences.find(p=>p.id==='user')?.transformationStart||data.dailyStates[0]?.date||date;const elapsed=Math.max(0,daysApart(date,start)),duration=config.durationWeeks*7;const rawCheckins=data.checkins.filter(c=>c.type==='weekly'&&c.date>=start&&c.date<=date).sort((a,b)=>a.date.localeCompare(b.date));const checkins=Object.values(Object.fromEntries(rawCheckins.map(c=>[weekStart(c.date),c])));const weight=trend(data.metrics.filter(m=>m.date>=start),'weight',date,economy.transformation),waist=trend(data.metrics.filter(m=>m.date>=start),'waist',date,economy.transformation);const controlled=data.sessions.filter(s=>safeSession(s)&&s.date>=start).flatMap(s=>s.logs.filter(l=>l.form).map(l=>({...l,date:s.date})));let strengthKept=false,strengthEvidence=[];for(const first of controlled.filter(l=>daysApart(l.date,start)<7&&l.weight>0)){const recent=controlled.find(l=>l.exerciseId===first.exerciseId&&daysApart(l.date,first.date)>=7&&((data.exercises.find(e=>e.id===first.exerciseId)?.resistance==='assistance'||['assisted-dip','assisted-pullup'].includes(first.exerciseId))?l.weight<=first.weight:l.weight>=first.weight)&&l.reps>=first.reps);if(recent){strengthKept=true;strengthEvidence=[first.id,recent.id];break}}return {start,elapsed,duration,config,weight,waist,checkins,halfway:elapsed>=Math.ceil(duration/2)&&checkins.length>=2,complete:elapsed>=duration&&checkins.length>=economy.transformation.minimumCheckins,strengthKept,strengthEvidence,mastery:data.masteryAwards.filter(a=>a.date>=start),records:data.recordEvents.filter(r=>r.date>=start),activeDays:activityDates(data).filter(d=>d>=start).length}}
export function bossProgress(data,date){const goals=goalStatuses(data.goals,data.skillDefinitions,data.masteryAwards);return bosses.map(b=>{let complete=false,evidence=[],steps=[];if(b.goal){const g=goals.find(g=>g.id===b.goal);steps=[...(g?.dependencies||[]),{id:b.goal,name:g?.name||b.goal,proven:!!g?.ownProof}];complete=!!g?.proven;evidence=data.masteryAwards.filter(a=>data.skillDefinitions.find(s=>s.id===a.skill)?.levelDefinitions.find(l=>l.id===a.levelId)?.provesGoal&&steps.some(step=>step.id===data.skillDefinitions.find(s=>s.id===a.skill).levelDefinitions.find(l=>l.id===a.levelId).provesGoal)).map(a=>({store:'masteryAwards',id:a.id}))}else if(b.skill){const skill=data.skillDefinitions.find(s=>s.id===b.skill),target=skill?.levelDefinitions.findIndex(l=>l.id===b.levelId);steps=skill?.levelDefinitions.slice(0,target+1).map(l=>({id:l.id,name:l.name,proven:data.masteryAwards.some(a=>a.skill===b.skill&&a.levelId===l.id)}))||[];complete=steps.length>0&&steps.every(s=>s.proven);evidence=data.masteryAwards.filter(a=>a.skill===b.skill&&steps.some(s=>s.id===a.levelId)).map(a=>({store:'masteryAwards',id:a.id}))}else {const t=transformationSummary(data,date);steps=[{name:'Configured journey elapsed',proven:t.elapsed>=t.duration},{name:'Logged transformation check-ins',proven:t.checkins.length>=data.gameConfigurations[0].transformation.minimumCheckins}];complete=t.complete;evidence=t.checkins.map(c=>({store:'checkins',id:c.id}))}return {...b,complete,evidence,steps,cleared:data.bossClears.find(c=>c.id===b.id)||null,percent:steps.length?Math.round(steps.filter(s=>s.proven).length/steps.length*100):0}})}
export function questCandidates(data,date){const result=[],profile=data.equipmentProfiles.find(p=>p.id===data.preferences.find(p=>p.id==='user')?.equipmentContext)||data.equipmentProfiles[0],goals=goalStatuses(data.goals,data.skillDefinitions,data.masteryAwards),root=goals.find(g=>g.id==='first-pullup');for(const skill of data.skillDefinitions){if(skill.sport&&(!data.preferences.find(p=>p.id==='user')?.sports))continue;const level=currentLevel(skill,data),ex=data.exercises.find(e=>e.id===level.exerciseId);if(!ex||!equipmentAllows(ex,profile))continue;const state=evaluateLevel(skill,level,data);if(state.dominated)continue;const linked=level.provesGoal&&(root?.id===level.provesGoal||root?.dependencies.some(g=>g.id===level.provesGoal&&!g.proven));if(!linked&&skill.id!=='grip')continue;const r=state.trials.find(t=>!t.complete)||state.trials[0];result.push({id:'dominance:'+date+':'+skill.id+':'+level.id,type:'Dominance',name:ex.name+' · '+r.pillar,description:'Practice the unfinished requirement; XP never bypasses proof.',date,deadline:date,priority:linked?1:2,minutes:ex.category==='Grip'?6:12,effort:'Controlled',goal:linked?'first-pullup':level.provesGoal||null,chainId:linked?'road-to-gravity':null,prerequisites:linked?root.dependencies.filter(g=>g.proven).map(g=>g.id):[],skill:skill.id,levelId:level.id,trialId:r.id,exerciseId:r.exerciseId||ex.id,reward:{xp:15,coins:3},condition:'trial',optional:true})}for(const p of pillarState(data,date).filter(p=>p.planned))result.push({id:'pillar-quest:'+date+':'+p.id,type:p.mode==='Recovery'?'Recovery':'Daily',name:p.name,date,deadline:date,priority:1,minutes:p.minutes,effort:p.mode,goal:null,pillarId:p.id,reward:{xp:0,coins:0},condition:'pillar',optional:false});result.push({id:'routine:'+date,type:'Personal',name:'Your planned routine',date,deadline:date,priority:2,minutes:5,effort:'Easy',condition:'routine',reward:{xp:0,coins:0},optional:true});result.push({id:'side:'+date,type:'Side',name:'Optional, after your plan',description:'Useful Extra Training after your planned day is honored. Save it for later if a protected commitment is near.',date,deadline:date,priority:3,minutes:12,effort:'Optional / controlled',condition:'extra',reward:{xp:10,coins:2},optional:true});
result.push({id:'recovery:'+date,type:'Recovery',name:'Smart Recovery',description:'Complete light or recovery work. Progress does not require maximal effort.',date,deadline:date,priority:2,minutes:8,effort:'Easy',condition:'recovery',reward:{xp:5,coins:0},optional:true});
const week=weekStart(date),end=new Date(week+'T12:00:00');end.setDate(end.getDate()+6);result.push({id:'transformation-checkin:'+week,type:'Transformation',name:'Transformation / weekly check-in',date:week,deadline:dayKey(end),priority:2,minutes:5,effort:'Reflection',condition:'transformation-checkin',reward:{xp:0,coins:0},optional:true});
result.push({id:'boss-quest:gravity',type:'Boss',name:'Gravity I',description:'Complete the evidence-driven First Strict Pull-Up path.',date,deadline:dayKey(new Date(new Date(date+'T12:00:00').getTime()+365*86400000)),priority:3,minutes:12,effort:'Controlled / only when prepared',condition:'boss',bossId:'gravity',reward:{xp:0,coins:0},optional:true});return result}
export function balanceKept(data,date){if(!dailyClear(data,date))return false;const blocks=data.events.filter(e=>e.category==='Personal Time'&&e.name.toLowerCase().includes('bae')&&e.date===date&&!['SKIPPED'].includes(e.status));if(!blocks.length)return false;return blocks.every(b=>data.sessions.filter(s=>s.kind==='Extra'&&s.status==='completed').every(s=>{const start=Date.parse(s.startedAt),end=Date.parse(s.completedAt||s.endedAt);return Number.isFinite(start)&&Number.isFinite(end)&&(end<=eventStart(b).getTime()||start>=eventStart(b).getTime()+b.durationMinutes*60000)}))}
export function weeklyGameSummary(data,date){const start=weekStart(date),within=r=>r.date>=start&&r.date<=date;const ledger=data.rewardLedger.filter(within);return {start,xp:ledger.reduce((n,r)=>n+r.amount,0),coins:ledger.filter(r=>r.coins>0).reduce((n,r)=>n+r.coins,0),mastery:data.masteryAwards.filter(within).length,prs:data.recordEvents.filter(r=>within(r)&&r.previous!==null).length,quad:data.rewardLedger.filter(r=>within(r)&&r.sourceType==='quad').length,personal:weeklyPersonalSummary(data.events,new Date(date+'T23:59:59')).completed}}
